"""Pack Blender renders using installed ImageMagick. No pip/npm dependencies."""
import base64, json, subprocess, gzip
from pathlib import Path
ROOT=Path(__file__).resolve().parent
ASSETS=ROOT.parent/'assets'
meta=json.loads((ROOT/'atlas.json').read_text())
names=list(meta['sprites'])
# Fixed cells keep the pivot identical for every asset and avoid crop jitter.
# Preserve soft shadows. Threshold only the very faint catcher noise instead of
# turning alpha into a hard silhouette.
args=['magick','-size',f"{meta['width']}x{meta['height']}",'canvas:none']
for name in names:
    x,y,_,_=meta['sprites'][name]
    args += ['(',str(ROOT/'renders'/f'{name}.png'),'-channel','A','-evaluate','Subtract','2%','+channel',')','-geometry',f'+{x}+{y}','-composite']
args += ['-define','webp:method=6','-quality','79',str(ASSETS/'frontier.webp')]
subprocess.run(args,check=True)
data=(ASSETS/'frontier.webp').read_bytes()
encoded=base64.b64encode(data).decode()
(ASSETS/'atlas-data.ts').write_text('// Generated by art/pack.py. Embedded for the network-free game sandbox.\nexport const frontierAtlas = "data:image/webp;base64,'+encoded+'";\n')
(ROOT/'atlas-layout.ts').write_text('// Generated by art/render.py and art/pack.py.\nexport const frontierLayout = '+json.dumps(meta,indent=2)+' as const;\n')
# A labelled contact sheet is review evidence, never imported by the game.
args=['magick','montage']
for n in names:
    args+=['-label',n,str(ROOT/'renders'/f'{n}.png')]
args+=['-background','#211a28','-fill','#f3edf7','-font',subprocess.check_output(['fc-match','-f','%{file}','sans'],text=True),'-pointsize','12','-geometry','160x160+8+8','-tile','6x',str(ROOT/'contact-sheet.png')]
subprocess.run(args,check=True)
print(json.dumps({'sprites':len(names),'webpBytes':len(data),'dataUriBytes':len(encoded)+23,'gzipDataModuleBytes':len(gzip.compress((ASSETS/'atlas-data.ts').read_bytes(),mtime=0))},indent=2))
# Self-contained review of the actual compressed atlas at mobile tile scale.
html='''<!doctype html><meta charset="utf-8"><style>
*{box-sizing:border-box}body{margin:0;color:var(--foreground,#f3edf7);font:14px system-ui}button,input{font:inherit}p{line-height:1.5}.controls{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(104px,1fr));gap:8px}.card{background:var(--card,#211a28);border-radius:12px;text-align:center;padding:8px 0}.stage{height:105px;position:relative;overflow:hidden}.origin{position:absolute;left:50%;top:74px}.sprite{position:absolute;pointer-events:none;background-repeat:no-repeat;background-image:url(DATA)}.name{font-size:12px;display:block;margin-top:4px}.swatch{border:1px solid var(--border,#594462);background:var(--secondary,#35243f);color:inherit;border-radius:8px;padding:6px 10px}.board{height:300px;position:relative;overflow:hidden;background:#211a28;border-radius:16px;margin-bottom:16px}.board-inner{position:absolute;left:50%;top:55px}.ring{position:absolute;transform:translate(-50%,-50%);border:2px solid #c48af2;border-radius:50%;background:#6a0dad66;width:30px;height:15px}
</style><p>Gaute Brewtown models, rendered in Blender. Adjust the tile width to inspect the silhouettes at phone size.</p><div class="controls"><label>Tile width <input id="size" type="range" min="48" max="96" value="72"> <output id="value">72 px</output></label><button class="swatch" id="theme">Switch terrain backdrop</button></div><div class="board"><div class="board-inner" id="board"></div></div><div class="grid" id="grid"></div><script>
const meta=META, names=Object.keys(meta.sprites);let tile=72;
function sprite(name,w){const [x,y]=meta.sprites[name],s=w/meta.groundWidth,e=document.createElement('div');e.className='sprite';Object.assign(e.style,{width:meta.cell*s+'px',height:meta.cell*s+'px',left:-meta.anchor[0]*s+'px',top:-meta.anchor[1]*s+'px',backgroundSize:meta.width*s+'px '+meta.height*s+'px',backgroundPosition:-x*s+'px '+-y*s+'px'});return e}
function draw(){document.querySelector('#grid').replaceChildren();for(const n of names){const c=document.createElement('div');c.className='card';const st=document.createElement('div');st.className='stage';const origin=document.createElement('div');origin.className='origin';if(!names.slice(0,8).includes(n))origin.append(sprite('meadow',tile));if(names.slice(19).includes(n)){const ring=document.createElement('div');ring.className='ring';origin.append(ring)}origin.append(sprite(n,tile));st.append(origin);const text=document.createElement('span');text.className='name';text.textContent=n;c.append(st,text);document.querySelector('#grid').append(c)}const b=document.querySelector('#board');b.replaceChildren();const map=['water','spring','pineWoodland','hill','water','meadow','woodland','hopGrove','meadow','meadow','meadow','woodland','barleyMeadow','meadow','meadow','meadow'];const over={5:'brewhouse',9:'barleyField',10:'brewer',14:'cargoBike'};const cells=[];for(let c=0;c<4;c++)for(let r=0;r<4;r++)cells.push({c,r,y:r*31.177+(c%2)*15.588});cells.sort((a,b)=>a.y-b.y);for(const {c,r,y} of cells){const i=r*4+c,e=document.createElement('div');e.style.position='absolute';e.style.left=(c*54-81)+'px';e.style.top=y+'px';e.append(sprite(map[i],72));if(over[i])e.append(sprite(over[i],72));b.append(e)}}
document.querySelector('#size').oninput=e=>{tile=+e.target.value;document.querySelector('#value').textContent=tile+' px';draw()};let light=false;document.querySelector('#theme').onclick=()=>{light=!light;document.querySelectorAll('.stage,.board').forEach(e=>e.style.background=light?'#faf8fc':'#211a28')};draw();</script>'''
html=html.replace('DATA','data:image/webp;base64,'+encoded).replace('META',json.dumps(meta))
(ROOT/'review.html').write_text(html)
formatter=ROOT.parents[2]/'node_modules/.bin/vp'
subprocess.run([str(formatter),'fmt',str(ROOT/'atlas.json'),str(ROOT/'atlas-layout.ts'),str(ASSETS/'atlas-data.ts'),str(ROOT/'review.html')],check=True,cwd=ROOT.parents[2])
